from collections import defaultdict, deque

def solve(n, adj, queries):
	visited = set()
	queue = deque()

	def bfs(time):
		while queue and time > 0:
			size = len(queue)
			for _ in range(size):
				u = queue.popleft()
				for nei in adj[u]:
					if nei in visited:
						continue
					visited.add(nei)
					queue.append(nei)
			time -= 1
	for (t, val) in queries:
		if t == 1:
			if val in visited:
				continue
			visited.add(val)
			queue.append(val)
		elif t == 2:
			bfs(val)
		elif val in visited:
			print('YES')
		else:
			print('NO')
